import gzip,io
for level in [0,1,9]:
 for write_empty in [False,True]:
  buffer=io.BytesIO()
  writer=gzip.GzipFile(fileobj=buffer,mode='wb',compresslevel=level,mtime=0)
  if write_empty:writer.write(b'')
  writer.close()
  print(buffer.getvalue().hex(),gzip.decompress(buffer.getvalue()))

